<?php $value = static fn(string $key): string => old_value($old, $key, (string) ($page[$key] ?? '')); $invalid = static fn(string $key): string => field_error($errors, $key) ? ' aria-invalid="true" aria-describedby="' . str_replace('_', '-', $key) . '-error"' : ''; ?>
<div class="dashboard-page-heading organizer-page-heading"><div><p class="dashboard-kicker"><i class="ph ph-file-text" aria-hidden="true"></i><span>Fixed public page</span></p><h1>Edit <?= e($page['title']) ?></h1><p>The route <code>/<?= e($page['slug']) ?></code> is fixed. Content is plain text and rendered as paragraphs.</p></div><a class="button button--quiet" href="/admin/cms"><i class="ph ph-arrow-left" aria-hidden="true"></i><span>Back to content</span></a></div>
<?php foreach (['meta_title', 'meta_description'] as $missingField): ?><?php if ($message = field_error($errors, $missingField)): ?><p id="<?= e(str_replace('_', '-', $missingField)) ?>-error" class="field-error mt-3" role="alert"><?= e($message) ?></p><?php endif; ?><?php endforeach; ?>
<form class="dashboard-panel organizer-form mt-8" action="/admin/cms/pages/<?= e($page['slug']) ?>" method="post"><input type="hidden" name="_token" value="<?= e($csrfToken) ?>"><?php if ($message = field_error($errors, 'page')): ?><div class="form-alert" role="alert"><?= e($message) ?></div><?php endif; ?><section class="organizer-form__section" aria-labelledby="page-content"><div class="organizer-form__heading"><span><i class="ph ph-text-aa" aria-hidden="true"></i></span><div><h2 id="page-content">Page content</h2><p>Separate paragraphs with a blank line. HTML is not accepted.</p></div></div><div class="grid gap-5 sm:grid-cols-2"><div class="field-group sm:col-span-2"><label for="title">Title</label><input id="title" name="title" maxlength="180" value="<?= $value('title') ?>" required<?= $invalid('title') ?>><?php if ($m=field_error($errors,'title')):?><p id="title-error" class="field-error" role="alert"><?=e($m)?></p><?php endif;?></div><div class="field-group sm:col-span-2"><label for="content">Content</label><textarea id="content" name="content" rows="14" maxlength="20000" required<?= $invalid('content') ?>><?= $value('content') ?></textarea><?php if ($m=field_error($errors,'content')):?><p id="content-error" class="field-error" role="alert"><?=e($m)?></p><?php endif;?></div><div class="field-group"><label for="meta_title">Meta title <span class="field-label-note">Optional</span></label><input id="meta_title" name="meta_title" maxlength="190" value="<?= $value('meta_title') ?>"<?= $invalid('meta_title') ?>></div><div class="field-group"><label for="meta_description">Meta description <span class="field-label-note">Optional</span></label><textarea id="meta_description" name="meta_description" rows="3" maxlength="320"<?= $invalid('meta_description') ?>><?= $value('meta_description') ?></textarea></div></div></section><div class="organizer-form__actions"><p><i class="ph ph-info" aria-hidden="true"></i><span>Saving content does not change publication status.</span></p><button class="button button--primary" type="submit"><i class="ph ph-floppy-disk" aria-hidden="true"></i><span>Save page</span></button></div></form>
